26	ArchitectureId PlatformArchitectureOrDie(PlatformId platform) {
27	  ArchitectureId arch = PlatformArchitecture(platform);
28	  if (arch == ArchitectureId::kUndefined) {
29	    LOG_FATAL("Undefined architecture for platform: ", EnumStr(platform));
30	  }
31	  return arch;
32	}
