34	ArchitectureId PlatformArchitecture(PlatformId platform) {
35	  switch (platform) {
36	    case PlatformId::kIntelSkylake:
37	    case PlatformId::kIntelHaswell:
38	    case PlatformId::kIntelBroadwell:
39	    case PlatformId::kIntelIvybridge:
40	    case PlatformId::kIntelCascadelake:
41	    case PlatformId::kAmdRome:
42	    case PlatformId::kIntelIcelake:
43	    case PlatformId::kAmdMilan:
44	    case PlatformId::kIntelSapphireRapids:
45	    case PlatformId::kAmdGenoa:
46	    case PlatformId::kIntelCoffeelake:
47	    case PlatformId::kIntelAlderlake:
48	    case PlatformId::kIntelEmeraldRapids:
49	    case PlatformId::kAmdRyzenV3000:
50	    case PlatformId::kIntelGraniteRapids:
51	    case PlatformId::kAmdSiena:
52	    case PlatformId::kAmdTurin:
53	    case PlatformId::kAmdVenice:
54	      return ArchitectureId::kX86_64;
55	    case PlatformId::kArmNeoverseN1:
56	    case PlatformId::kArmNeoverseN2:
57	    case PlatformId::kAmpereOne:
58	    case PlatformId::kArmNeoverseV2:
59	    case PlatformId::kArmNeoverseN3:
60	      return ArchitectureId::kAArch64;
61	    case PlatformId::kUndefined:
62	    case PlatformId::kAny:
63	    case PlatformId::kNonExistent:
64	    default:
65	      return ArchitectureId::kUndefined;
66	  }
67	}
