33	// A quick test to catch when new platforms get added to prod.
34	// If this test becomes flaky then a new entry should be added to the PlatformId
35	// enum.
36	TEST(PlatformTest, CurrentPlatformId) {
37	  ASSERT_NE(CurrentPlatformId(), PlatformId::kUndefined)
38	      << "New platform was added to the fleet. Look at the error log and update"
39	      << " PlatformId enum accordingly";
40	
41	  ASSERT_EQ(PlatformArchitecture(CurrentPlatformId()), Host::architecture_id);
42	}
