119	// Transforms the snapshot's MemoryBytes into Snap-compatible format.
120	// Specifically, ensures that all MemoryBytes are fragmented according to `opts`
121	// in both the Snapshot and all EndStates. Populates all EndStates with all
122	// writable bytes from the parent Snapshot.
123	absl::Status SnapifyMemoryBytes(Snapshot &snapshot,
124	                                const SnapifyOptions &opts) {
125	  MemoryState memory_state =
126	      MemoryState::MakeInitial(snapshot, MemoryState::kZeroMappedBytes);
127	
128	  CompressionQuery should_compress_initial = &ShouldNeverCompress;
129	  if (opts.compress_repeating_bytes) {
130	    if (opts.support_direct_mmap) {
131	      should_compress_initial = &ShouldCompressNonExecutable;
132	    } else {
133	      should_compress_initial = &ShouldAlwaysCompress;
134	    }
135	  }
136	
137	  ASSIGN_OR_RETURN_IF_NOT_OK(
138	      Snapshot::MemoryBytesList snapified_memory_bytes_list,
139	      SnapifyMemoryByteList(memory_state, should_compress_initial));
140	  RETURN_IF_NOT_OK(
141	      snapshot.ReplaceMemoryBytes(std::move(snapified_memory_bytes_list)));
142	
143	  Snapshot::EndStateList end_states = snapshot.expected_end_states();
144	  snapshot.set_expected_end_states({});
145	
146	  for (Snapshot::EndState &end_state : end_states) {
147	    if (end_state.IsComplete().ok()) {
148	      MemoryState memory_state =
149	          MemoryState::MakeInitial(snapshot, MemoryState::kZeroMappedBytes);
150	      // Apply deltas from the current end state.
151	      memory_state.SetMemoryBytes(end_state.memory_bytes());
152	
153	      // Keep just the writable pages in memory_state.
154	      snapshot.mapped_memory_map().Iterate(
155	          [&memory_state](auto start, auto limit, MemoryPerms perms) {
156	            if (!perms.Has(MemoryPerms::kWritable)) {
157	              // Remove all non-writable mappings (and bytes) from the memory
158	              // state.
159	              memory_state.RemoveMemoryMapping(start, limit);
160	            }
161	          });
162	      ASSIGN_OR_RETURN_IF_NOT_OK(
163	          Snapshot::MemoryBytesList snapified_end_state_memory_bytes_list,
164	          SnapifyMemoryByteList(memory_state, opts.compress_repeating_bytes
165	                                                  ? &ShouldAlwaysCompress
166	                                                  : &ShouldNeverCompress));
167	      RETURN_IF_NOT_OK(end_state.ReplaceMemoryBytes(
168	          std::move(snapified_end_state_memory_bytes_list)));
169	    } else {
170	      DCHECK(opts.allow_undefined_end_state);
171	    }
172	    RETURN_IF_NOT_OK(snapshot.can_add_expected_end_state(end_state));
