76	      args.thread_idx);
77	
78	  int iteration = 0;
79	  for (iteration = 0; !ctx->ShouldStop() && !args.cpus.empty(); iteration++) {
80	    absl::Time start_time = absl::Now();
81	    absl::Duration time_budget = ctx->deadline() - start_time;
82	    if (time_budget <= absl::ZeroDuration()) {
83	      break;
84	    }
85	    RunnerOptions runner_options = args.runner_options;
86	    int target_cpu = args.cpus[iteration % args.cpus.size()];
87	    runner_options.set_cpu(target_cpu);
88	    runner_options.set_wall_time_budget(time_budget);
89	    VLOG_INFO(1, "T", args.thread_idx, " time budget ",
90	              absl::FormatDuration(time_budget));
91	    int shard_idx = next_corpus_generator();
92	
93	    if (shard_idx == NextCorpusGenerator::kEndOfStream) {
94	      VLOG_INFO(0, "T", args.thread_idx,
95	                " Reached end of stream in sequential mode");
96	      break;
97	    }
98	
99	    const InMemoryShard &shard = args.corpora->shards[shard_idx];
100	    RunnerDriver driver =
101	        RunnerDriver::ReadingRunner(args.runner, shard.file_path, shard.name);
102	    RunnerDriver::RunResult run_result = driver.Run(runner_options);
103	
104	    absl::Duration elapsed_time = absl::Now() - start_time;
105	
106	    std::string log_msg = absl::StrCat(
107	        "T", args.thread_idx, " cpu: ", target_cpu, " corpus: ", shard.name,
108	        " time: ", absl::ToInt64Seconds(elapsed_time),
109	        " exit_status: ", RunResultToDebugString(run_result));
110	    if (!run_result.execution_result().ok()) {
111	      LOG_ERROR(log_msg, " ", run_result.execution_result().DebugString());
112	      if (run_result.postfailure_checksum_status() ==
113	          RunnerPostfailureChecksumStatus::kMismatch) {
114	        LOG_ERROR("Snapshot checksum mismatch");
115	      }
116	    } else {
117	      VLOG_INFO(0, log_msg);
118	    }
119	
120	    if (!ctx->OfferRunResult(std::move(run_result))) {
121	      LOG_ERROR(
122	          "T", args.thread_idx,
123	          " Result processing queue is stuck, some results won't be logged");
124	    }
125	  }
126	
127	  ctx->Stop();
128	  VLOG_INFO(0, "T", args.thread_idx, " stopped after ", iteration,
