147	CpuExecutionContext* OrchestratorInit(
148	    absl::Time deadline, int num_threads,
149	    const CpuExecutionContext::ResultCallback& result_cb) {
150	  static CpuExecutionContext ctx(deadline, num_threads, result_cb);
151	
152	  struct sigaction sigact = {};
153	  sigact.sa_handler = [](int) {
154	    ABSL_RAW_LOG(INFO, "SIGINT/SIGALRM caught; shutting down worker threads\n");
155	    ctx.Stop();
156	  };
157	  sigaction(SIGINT, &sigact, nullptr);
158	  sigaction(SIGALRM, &sigact, nullptr);
159	
160	  if (auto overrun = absl::GetFlag(FLAGS_watchdog_allowed_overrun);
161	      overrun > absl::ZeroDuration()) {
162	    absl::Duration watchdog_timeout = deadline - absl::Now() + overrun;
163	    std::thread watchdog([watchdog_timeout]() {
164	      absl::SleepFor(watchdog_timeout);
165	      ABSL_RAW_LOG(ERROR, "Terminated by watchdog\n");
166	      _exit(EXIT_SUCCESS);
167	    });
168	    watchdog.detach();
169	  }
170	
171	  return &ctx;
172	}
