63	// Runs the orchestrator event loop.
64	// NOTE: This method is not reentrant. Must be called by the main thread.
65	template <typename RunResultT>
66	void ExecutionContext<RunResultT>::EventLoop() {
67	  constexpr absl::Duration kTimeout = absl::Seconds(10);
68	  while (!ShouldStop()) {
69	    std::vector<RunResultT> current_results;
70	    current_results.reserve(num_threads_);
71	    {
72	      bool timed_out = mu_.LockWhenWithTimeout(
73	          absl::Condition(this, &ExecutionContext::ShouldWakeUp), kTimeout);
74	      VLOG_INFO(2, "Result processor woke up, queue size = ",
75	                invocation_results_.size(), " due to timeout? = ", timed_out);
76	      invocation_results_.swap(current_results);
77	      mu_.unlock();  // NOLINT: deprecated-declarations
78	    }
79	
80	    ProcessResultQueueImpl(current_results);
81	  }
82	}
