213	  const uint64_t code_start_addr =
214	      InstructionsToCodeAddress(code, config.code_range.start_address,
215	                                config.code_range.num_bytes, kPageSize);
216	
217	  UContext<X86_64> uctx = {};
218	
219	  // These are the values of %cs and %ss kernel sets for userspace programs.
220	  // RestoreUContext does not modify the two but the runner still verifies
221	  // the values didn't change during snapshot execution.
222	  uctx.gregs.cs = 0x33;
223	  uctx.gregs.ss = 0x2b;
224	
225	  // Raise IF (0x200) and the reserved 0x2 which is always on according to
226	  // https://en.wikipedia.org/wiki/FLAGS_register
227	  // The IF is only accessible to the kernel, assume it's always set in
228	  // user mode.
229	  uctx.gregs.eflags = 0x202;
230	
231	  // RSP points to the bottom of the writable page.
232	  uctx.gregs.rsp = config.data1_range.start_address + kPageSize;
233	  uctx.gregs.rip = code_start_addr;
234	
235	  memset(&uctx.fpregs, 0, sizeof(uctx.fpregs));
236	  // Initialize FCW and MXCSR to sensible defaults that mask as many exceptions
237	  // as possible with the idea to allow generated snapshots execute more code.
238	  uctx.fpregs.mxcsr = 0x1f80;
239	  uctx.fpregs.mxcsr_mask = 0xffff;
240	  uctx.fpregs.fcw = 0x37f;
241	  // Non-zero initialization of at least 1 XMM register inhibits init state
242	  // optimization on Arcadia. This is a workaround for erratum 1386 "XSAVES
243	  // Instruction May Fail to Save XMM Registers to the Provided State Save
244	  // Area". See https://www.amd.com/system/files/TechDocs/56683-PUB-1.07.pdf
245	  uctx.fpregs.xmm[0] = 0xcafebabe;
246	
247	  return uctx;
248	}
