250	template <>
251	UContext<AArch64> GenerateUContextForInstructions(
252	    absl::string_view code, const FuzzingConfig<AArch64>& config) {
253	  const uint64_t code_start_addr =
254	      InstructionsToCodeAddress(code, config.code_range.start_address,
255	                                config.code_range.num_bytes, kPageSize);
256	
257	  // Setup register state
258	  UContext<AArch64> uctx = {};
259	
260	  // x30 will be aliased to pc as an artifact of how we jump into the code.
261	  uctx.gregs.x[30] = code_start_addr;
262	  uctx.gregs.pc = code_start_addr;
263	
264	  // sp points off the end of the stack.
265	  uctx.gregs.sp =
266	      config.stack_range.start_address + config.stack_range.num_bytes;
267	
268	  // HACK seed the addresses of the memory regions in registers.
269	  uctx.gregs.x[6] = config.data1_range.start_address;
270	  uctx.gregs.x[7] = config.data2_range.start_address;
271	
272	  // Note: FPCR of zero means round towards nearest and no exceptions enabled.
273	
274	  return uctx;
275	}
