48	void SetSignalHandlers() {
49	  struct sigaction sigact = {};
50	  sigact.sa_flags = SA_ONSTACK;
51	  sigact.sa_handler = [](int received_signum) {
52	    if (received_signum != SIGINT) return;
53	    const char msg[] = "\n[!] Ctrl-C pressed: winding down\n";
54	    [[maybe_unused]] auto write_res =
55	        write(STDERR_FILENO, msg, sizeof(msg) - 1);
56	    global_stop_condition.RequestStop(EXIT_FAILURE, "Ctrl-C pressed");
57	  };
58	  sigaction(SIGINT, &sigact, nullptr);
59	}
