64	using fuzztest::internal::MutationInputRef;
65	
66	class SilifuzzCentipedeCallbacks
67	    : public fuzztest::internal::CentipedeDefaultCallbacks {
68	 public:
69	  SilifuzzCentipedeCallbacks(const fuzztest::internal::Environment& env,
70	                             fuzztest::internal::StopCondition& stop_condition)
71	      : CentipedeDefaultCallbacks(env, stop_condition),
72	        arch_(absl::GetFlag(FLAGS_arch)),
73	        x86_64_mutator_(fuzztest::internal::GetRandomSeed(env.seed),
74	                        env.crossover_level / 100.0, env.max_len),
75	        aarch64_mutator_(fuzztest::internal::GetRandomSeed(env.seed),
76	                         env.crossover_level / 100.0, env.max_len) {}
77	
78	  std::vector<fuzztest::internal::Mutant> Mutate(
79	      absl::Span<const fuzztest::internal::MutationInputRef> inputs,
80	      size_t num_mutants) override {
81	    // Fall back to the byte mutator if the architecture was not specified.
82	    if (arch_ == ArchitectureId::kUndefined) {
83	      return fuzztest::internal::CentipedeDefaultCallbacks::Mutate(inputs,
84	                                                                   num_mutants);
85	    }
86	
87	    // Init
88	    std::vector<fuzztest::internal::Mutant> mutants{num_mutants};
89	    if (num_mutants == 0) return mutants;
90	
91	    // Re-wrap the input vector so the mutator doesn't need to depend on
92	    // Centipede's types.
93	    std::vector<const std::vector<uint8_t> *> tmp;
94	    tmp.reserve(inputs.size());
95	    for (const MutationInputRef &input : inputs) {
96	      tmp.push_back(&input.data);
97	    }
98	
99	    // Mutate
100	    std::vector<fuzztest::internal::ByteArray> byte_array_mutants(num_mutants);
101	    switch (arch_) {
102	      case ArchitectureId::kX86_64:
103	        x86_64_mutator_.Mutate(tmp, num_mutants, byte_array_mutants);
104	        break;
105	      case ArchitectureId::kAArch64:
106	        aarch64_mutator_.Mutate(tmp, num_mutants, byte_array_mutants);
107	        break;
108	      default:
109	        LOG(FATAL) << "Unknown architecture: " << (int)arch_;
110	    }
111	
112	    for (size_t i = 0; i < num_mutants; ++i) {
113	      mutants[i].data = std::move(byte_array_mutants[i]);
114	    }
115	
116	    return mutants;
117	  }
118	
119	 private:
120	  ArchitectureId arch_;
121	  ProgramBatchMutator<X86_64> x86_64_mutator_;
122	  ProgramBatchMutator<AArch64> aarch64_mutator_;
123	};
